//! Grid geometry vs navi's shared/dem.py (expected values generated by running dem.grid_window).
use cache_offroad::grid::GridMeta;
use serde_json::Value;

#[test]
fn grid_meta_matches_navi_dem() {
    let cases: Value = serde_json::from_str(include_str!("fixtures/grid_cases.json")).unwrap();
    for c in cases.as_array().unwrap() {
        let b: Vec<f64> = c["b"].as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect();
        let m = GridMeta::from_bbox(b[0], b[1], b[2], b[3]);
        assert_eq!(m.rows as u64, c["rows"].as_u64().unwrap(), "{b:?}");
        assert_eq!(m.cols as u64, c["cols"].as_u64().unwrap(), "{b:?}");
        let near = |a: f64, e: f64| assert!((a - e).abs() <= 1e-12 * e.abs().max(1.0), "{a} vs {e} for {b:?}");
        near(m.cell_size_m, c["cell"].as_f64().unwrap());
        near(m.origin_lat, c["ol"].as_f64().unwrap());
        near(m.origin_lon, c["oo"].as_f64().unwrap());
        near(m.pixel_size_lat, c["psl"].as_f64().unwrap());
        near(m.pixel_size_lon, c["pso"].as_f64().unwrap());
        let (est_r, est_c) = GridMeta::estimate_shape(b[0], b[1], b[2], b[3]);
        assert_eq!((est_r, est_c), (m.rows, m.cols));
        assert_eq!(m.global_row0, c["y_min"].as_i64().unwrap() * 512 + c["row_start"].as_i64().unwrap());
        assert_eq!(m.global_col0, c["x_min"].as_i64().unwrap() * 512 + c["col_start"].as_i64().unwrap());
    }
}
